# The user-facing learning set is broader than a list of occupation tasks. Keep
# each type explicit so later integration cannot mistake a software option for
# a method, or a certification for evidence of competence.
def classify_item(label: str) -> str:
    s = label.casefold()
    if any(k in s for k in ("nvivo", "taguette", "spss", "python", "r/statistical", "stata", "jamovi", "gis", "software", "tool", "database", "records", "instrument", "networkx", "mesa", "casevo", "jupyter", "scikit", "statsmodels")):
        return "tool"
    if any(k in s for k in ("research design", "sampling", "interview", "observation", "analysis", "evaluation", "archival", "survey", "comparison", "modelling", "modeling", "method", "source criticism", "field recording", "forecasting", "content analysis", "thematic", "ethnographic", "document analysis", "statistical analysis", "spatial analysis")):
        return "method"
    if any(k in s for k in ("ethics", "communication", "writing", "stewardship", "reflexivity", "critical interpretation", "evidence appraisal", "stakeholder", "coordination", "reasoning", "validation", "data quality")):
        return "competency"
    if any(k in s for k in ("concept", "theory", "institution", "measurement", "population", "geography", "economic", "political", "psychological", "demographic", "logic", "chronology", "statistics/econometrics", "social/behavioural", "social theory", "anthropological", "historical", "communication theory", "crime/justice")):
        return "knowledge"
    return "skill"

for area_record in area_records:
    task = area_record["task_families"][0]
    source_ids = task["authoritative_work_source_ids"]
    explain_ids = task["explanatory_source_ids"]
    learn_ids = task["free_task_specific_learning_source_ids"]
    task["learning_items"] = []
    for label in task.pop("skills_knowledge_methods_competencies"):
        item_type = classify_item(label)
        task["learning_items"].append({
            "label": label,
            "type": item_type,
            "what_it_is": f"A {item_type.replace('_', ' ')} used to carry out or explain this task family; this wording is a research summary, not a claim that every practitioner needs every item.",
            "meaning_in_selected_programme": "Programme-specific meaning is not inferred here; connect this item to a selected programme only when its curriculum/outcomes and evidence locators support that connection.",
            "meaning_in_domain_and_area": f"Within {area_record['label']}, it supports the task family only where the stated question, evidence and output require it.",
            "role_application": "Role-level use must be stated in the role task family; this area-level record does not automatically assign the item to every role.",
            "evidence_source_ids": source_ids,
            "explanatory_source_ids": explain_ids,
            "free_task_specific_learning_resource_ids": learn_ids,
            "resource_gate": "research_candidate; check whether the linked resource teaches this exact item/use before any student display",
            "prerequisites_relationships_and_limits": "See task-family prerequisites, complements, alternatives and limits; do not treat the item as a credential or proof of competence."
        })
    task["skills_knowledge_methods_competencies"] = {
        "skills": [x["label"] for x in task["learning_items"] if x["type"] == "skill"],
        "knowledge": [x["label"] for x in task["learning_items"] if x["type"] == "knowledge"],
        "methods": [x["label"] for x in task["learning_items"] if x["type"] == "method"],
        "competencies": [x["label"] for x in task["learning_items"] if x["type"] == "competency"]
    }
    # Do not present a single general course as a task-specific learning link.
    # Retain it as an explainer, but require resource review before display.
    if explain_ids == learn_ids:
        task["free_task_specific_learning_source_ids"] = []
        task["free_learning_resource_finding"] = {
            "status": "none_verified_at_area_task_specific_level",
            "non_displayable": True,
            "note": "The available link explains the area but was not established as a task-specific teaching resource for the complete task family."
        }
    else:
        task["free_learning_resource_finding"] = {
            "status": "candidate_requires_link_and_scope_recheck",
            "non_displayable": True,
            "note": "The resource is separate from the explanatory source; verify that its actual content teaches this precise task before student display."
        }

