for role in role_records:
    name = role["source_role_label"]
    task = role["task_families"][0]
    esco_profile_url = next((x["url"] for x in task["authoritative_work_sources"] if "data.europa.eu/esco/occupation/" in x["url"]), sources["ESCO_OCCUPATIONS"]["url"])
    for item in task["skills_knowledge_methods_competencies"]:
        item["source_profile_url"] = esco_profile_url
        item["learning_link_status"] = "no_item_specific_free_learning_link_verified; do_not_assume_the_role_level_resource_teaches_this_item"
        item["item_verification_gate"] = "Confirm the exact ESCO concept definition, type (skill versus knowledge), source locator, and D078 task use before student display."
    resource_id, disposition, reason = ROLE_RESOURCE_REVIEW[name]
    task["free_task_specific_learning_source_ids"] = [resource_id] if resource_id else []
    task["free_learning_resource_finding"] = {
        "status": disposition,
        "non_displayable": True,
        "resource_source_id": resource_id,
        "scope_and_limit": reason,
        "review_gate": "Verify the live page, free access, lesson content, currentness, licensing/accessibility and fit to the exact selected task before student display."
    }
    if not resource_id:
        task["free_task_specific_learning_source_ids"] = []
    task["learning_item_taxonomy_note"] = "The canonical role record exposes ESCO-linked essential/optional skill strings. This ledger preserves those labels and their essential/optional distinction, but their source profile locators and exact knowledge-versus-skill typing still require item-level verification; do not display them as prerequisites based on list position alone."
    task["esco_profile_completeness_gate"] = "Open the exact ESCO profile URL and confirm its full occupation description, skills/knowledge links and their locators. The brief canonical summary is not a complete task standard."

